public static class Solution
{
    public static long Gcd(int a, int b)
    {
        long x = Math.Abs(a);
        long y = Math.Abs(b);
        while (y != 0)
        {
            long temp = x % y;
            x = y;
            y = temp;
        }
        return x;
    }
}

