public static class Solution
{
    public static long SumPrimes(int limit)
    {
        if (limit < 2) return 0;
        bool[] isPrime = new bool[limit + 1];
        for (int i = 2; i <= limit; i++)
        {
            isPrime[i] = true;
        }
        for (int i = 2; i * i <= limit; i++)
        {
            if (isPrime[i])
            {
                for (int j = i * i; j <= limit; j += i)
                {
                    isPrime[j] = false;
                }
            }
        }
        long sum = 0;
        for (int i = 2; i <= limit; i++)
        {
            if (isPrime[i])
            {
                sum += i;
            }
        }
        return sum;
    }
}

