public static class Solution
{
    public static int BinarySearch(int[] sorted, int target)
    {
        int left = 0;
        int right = sorted.Length;
        while (left < right)
        {
            int mid = left + (right - left) / 2;
            if (sorted[mid] < target)
            {
                left = mid + 1;
            }
            else
            {
                right = mid;
            }
        }
        if (left < sorted.Length && sorted[left] == target)
        {
            return left;
        }
        return -1;
    }
}

