public static class Solution
{
    public static Dictionary<string, string> ParseKeyValues(string s)
    {
        if (string.IsNullOrWhiteSpace(s))
        {
            return new Dictionary<string, string>();
        }

        string[] pairs = s.Split(';');
        Dictionary<string, string> result = new Dictionary<string, string>();
        foreach (string pair in pairs)
        {
            int equalIndex = pair.IndexOf('=');
            if (equalIndex <= 0 || equalIndex != pair.LastIndexOf('='))
            {
                throw new FormatException("Invalid key-value pair.");
            }

            string key = pair.Substring(0, equalIndex).Trim();
            string value = pair.Substring(equalIndex + 1).Trim();
            if (string.IsNullOrWhiteSpace(key))
            {
                throw new FormatException("Key cannot be empty.");
            }

            if (result.ContainsKey(key))
            {
                throw new FormatException("Duplicate key.");
            }

            result.Add(key, value);
        }

        return result;
    }
}

