public sealed record Color(byte Red, byte Green, byte Blue);

public static class Solution
{
    public static Color? ParseHexColor(string? text)
    {
        if (string.IsNullOrWhiteSpace(text))
        {
            return null;
        }

        string trimmed = text.Trim();
        if (trimmed.Length != 7)
        {
            return null;
        }

        if (trimmed[0] != '#')
        {
            return null;
        }

        for (int i = 1; i <= 6; i++)
        {
            char c = trimmed[i];
            if (!char.IsDigit(c) && !('a' <= c && c <= 'f') && !('A' <= c && c <= 'F'))
            {
                return null;
            }
        }

        byte red = byte.Parse(trimmed.Substring(1, 2), System.Globalization.CultureInfo.InvariantCulture);
        byte green = byte.Parse(trimmed.Substring(3, 2), System.Globalization.CultureInfo.InvariantCulture);
        byte blue = byte.Parse(trimmed.Substring(5, 2), System.Globalization.CultureInfo.InvariantCulture);
        return new Color(red, green, blue);
    }
}
